SCREENS['t-messages'] = (p) => {
  const ts = tasThreads(), cur = p.id && ts.find(t => t.id === p.id);
  if (cur) { cur.seen = cur.msgs.length; if (cur.lthread) { cur.lthread._tasSeen = cur.msgs.length; } else STORE.tas.threads.find(t => t.id === cur.id).seen = cur.msgs.length; }
  return `${pageA('Messages', 'Mirrored to email per settings. Retained and auditable — no delete.', `<button class="btn btn-primary" data-act="tasCompose">${ic('plus', 15)}New message</button>`)}<div class="msg-layout ${cur ? 'has-thread' : ''}"><div class="thread-list">${thBar('T', ts)}${thx('T', ts).map(t => `<button class="thread-item" data-go="t-messages" data-id="${t.id}" ${cur && cur.id === t.id ? 'aria-current="true"' : ''}><span class="ti-top">${t.msgs.length > (t.seen || 0) && t.msgs[t.msgs.length - 1][0] !== TME().name ? '<span class="unread-dot" style="margin:0"></span><span class="sr">Unread</span>' : ''}<span class="ti-sub">${esc(t.subject)}</span>${t.tag ? chip(t.tag, 'blue') : ''}</span><span class="xs muted">${esc(t.with.join(', '))}${t.tbd ? '' : ''}</span><span class="ti-last">${esc(t.msgs[t.msgs.length - 1][2])}</span></button>`).join('')}</div>
  <div class="chat">${cur ? `<div class="chat-h"><button class="btn btn-sm btn-ghost" data-go="t-messages" style="justify-self:start">${ic('back', 14)}All messages</button><h2>${esc(cur.subject)}</h2><div class="row"><span class="small muted">With ${esc(cur.with.join(', '))}</span>${cur.learner ? `<button class="btn btn-sm" data-act="tasFwd" data-id="${cur.id}">Forward to Academy admin</button>` : ''}</div></div><div class="chat-b">${cur.msgs.map(m => `<div class="bubble ${m[0] === TME().name ? 'me' : ''}"><span class="b-meta"><strong>${esc(m[0])}</strong> · ${fdt(m[1])}</span><span>${esc(m[2])}</span></div>`).join('')}</div><form class="chat-f" data-submit="tasReply" data-id="${cur.id}"><label class="sr" for="trep">Reply</label><textarea class="textarea" id="trep" rows="2" style="min-height:44px"></textarea><label class="icon-btn" aria-label="Attach">${ic('clip2')}<input type="file" class="sr"></label><button class="btn btn-primary" type="submit">${ic('send', 15)}Send</button></form>` : `${msgPaneEmpty(tasThreads(), 't-messages', 'tasCompose')}`}</div></div>`;
};
function tasPost(t, text) { if (t.lthread) { t.lthread.msgs.push({ me: false, from: TME().name, at: now().toISOString(), text }); t.lthread.unread = true; t.lthread._tasSeen = t.lthread.msgs.length; } else { const s = STORE.tas.threads.find(x => x.id === t.id); s.msgs.push([TME().name, now().toISOString(), text]); s.seen = s.msgs.length; } }
SUBMIT.tasReply = f => { const v = $('#trep').value.trim(); if (!v) return fieldErr('#trep', 'Write a reply'); const t = tasThreads().find(x => x.id === f.dataset.id); tasPost(t, v); tasLog('Messages', t.subject, 'Message sent', '—', t.with.join(', '), ''); render(); toast('Message sent.'); };
ACT.tasFwd = el => { const t = tasThreads().find(x => x.id === el.dataset.id); reasonDlg({ title: 'Forward to Academy admin', ok: 'Forward', label: 'Note for the Academy (required)', extra: `<div class="field"><label for="fw-to">To</label><select class="select" id="fw-to"><option>Finance (Academy Admin / Finance)</option><option>Rachel Hughes (Academic Admin)</option></select></div>`, onOk: r => { STORE.tas.threads.unshift({ id: 'TT-' + Date.now(), subject: 'Fwd: ' + t.subject, with: [$('#fw-to').value], tag: 'Forwarded', owner: TME().name, msgs: [[TME().name, now().toISOString(), r + '\n\n"' + t.msgs[t.msgs.length - 1][2] + '"']], seen: 1 }); tasPost(t, 'Forwarded to the Academy — they will reply to you directly.'); render(); toast('Forwarded. The learner sees "Forwarded to the Academy".'); } }); };
ACT.tasCompose = el => {
  const d = (el && el.dataset) || {};
  const rs = [...new Set(tasLearners(true).map(l => l.name + ' (Learner)').concat(['Dr Helen Carter (Academic Coordinator)', 'Rachel Hughes (Academic Admin)', 'Marcus Bell (Teacher)', 'James Pryce (Assessor)', 'Priyanka Shah (IQA)']))];
  openModal({ title: d.tag === 'Request change' ? 'Request change' : 'New message', body: `${d.tag ? chip(d.tag, 'blue') : ''}<div class="field"><label for="tm-to">To</label><select class="select" id="tm-to">${rs.map(r => `<option ${r === d.to ? 'selected' : ''}>${esc(r)}</option>`).join('')}</select></div><div class="field"><label for="tm-s">Subject</label><input class="input" id="tm-s" value="${esc(d.sub || (d.tag && d.tag.startsWith('Re:') ? d.tag : ''))}"></div><div class="field"><label for="tm-b">Message</label><textarea class="textarea" id="tm-b" rows="5"></textarea></div><div class="field"><label for="tm-f">Attachment</label><input class="input" type="file" id="tm-f"></div>`,
    actions: [{ label: 'Cancel' }, { label: 'Send', cls: 'btn-primary', fn: () => { const to = mval('#tm-to'), s = mval('#tm-s'), b = mval('#tm-b'); if (!s) { fieldErr('#tm-s', 'Enter a subject'); return false; } if (!b) { fieldErr('#tm-b', 'Write your message'); return false; } const L = tasLearners(true).find(l => to === l.name + ' (Learner)'); if (L && L.v) { STORE.worlds[L.v].threads.unshift({ id: 'tt' + Date.now(), subject: s, course: 'NVQ', with: [TME().name + ' (' + TME().roles.join(' + ') + ')'], unread: true, tas: TME().name, tag: d.tag, msgs: [{ me: false, from: TME().name, at: now().toISOString(), text: b }], _tasSeen: 1 }); notifyLearner(L.v, 'Other', 'New message', `${TME().name}: ${s}`, 'messages'); } else STORE.tas.threads.unshift({ id: 'TT-' + Date.now(), subject: s, with: [to], tag: d.tag || '', learner: !!L, owner: TME().name, msgs: [[TME().name, now().toISOString(), b]], seen: 1 }); tasLog('Messages', s, d.tag || 'Message sent', '—', to, ''); render(); toast('Message sent.'); } }] });
};

/* ---------- 6.12 Announcements ---------- */
SCREENS['t-announcements'] = () => `${pageA('Announcements', 'Audience limited to your own cohorts', `<button class="btn btn-primary" data-act="tasAnn">${ic('plus', 15)}New announcement</button>`)}${dt({ id: 'tann', name: 'Announcements', rows: STORE.tas.anns.filter(a => a.by === TME().name || TME().key === 'A'), cols: [{ k: 'title', l: 'Title', h: a => `<strong>${esc(a.title)}</strong>` }, { k: 'aud', l: 'Audience' }, { k: 'ch', l: 'Channels', v: a => a.ch.join(', ') }, { k: 'status', l: 'Status', h: a => chip(a.status, { Draft: 'grey', Scheduled: 'blue', Published: 'green', Expired: 'grey', Withdrawn: 'red' }[a.status]) }, { k: 'at', l: 'Date', h: a => fd(a.at), s: a => a.at }], act: a => a.status === 'Published' ? `<button class="btn btn-sm" data-act="tasAnnSt" data-id="${a.id}" data-s="Withdrawn">Withdraw</button>` : a.status === 'Scheduled' ? `<button class="btn btn-sm" data-act="tasAnnSt" data-id="${a.id}" data-s="Draft">Cancel before dispatch</button>` : '' })}`;
ACT.tasAnnSt = el => reasonDlg({ title: 'Change announcement', ok: 'Change announcement', onOk: r => { const a = STORE.tas.anns.find(x => x.id === el.dataset.id); tasLog('Announcements', a.title, el.dataset.s, a.status, el.dataset.s, r); a.status = el.dataset.s; render(); } });
ACT.tasAnn = () => openModal({ title: 'New announcement', size: 'lg', body: `<div class="field"><label for="tn-t">Title</label><input class="input" id="tn-t" value="Bring your reflective log on Thursday"></div><div class="field"><label for="tn-b">Message</label><textarea class="textarea" id="tn-b">Please bring your reflective log to Thursday's class.</textarea></div><div class="field"><label for="tn-f">Attachment</label><input class="input" type="file" id="tn-f"></div><fieldset class="stack" style="border:0;padding:0"><legend class="lbl">Audience (my cohorts only)</legend>${tasBatches().map((b, k) => `<label class="check small"><input type="checkbox" class="tn-b" value="${b.code}" ${k === 0 ? 'checked' : ''} data-onchange="tnCount">${esc(b.label)}</label>`).join('')}</fieldset><div class="row"><label class="check small"><input type="checkbox" checked>In-app</label><label class="check small"><input type="checkbox" checked>Email</label><label class="check small"><input type="checkbox">SMS</label></div><div class="field"><label for="tn-w">Timing</label><select class="select" id="tn-w"><option value="now">Send now</option><option value="sched">Schedule</option></select></div><p class="small" id="tn-c">Recipients: <strong>${tasLearners(true).filter(l => l.batch.code === (tasBatches()[0] || {}).code).length}</strong></p>`,
  actions: [{ label: 'Preview', cls: 'btn', fn: () => { toast('Preview: ' + mval('#tn-t'), 'info'); return false; } }, { label: 'Publish', cls: 'btn-primary', fn: () => { const codes = $$('.tn-b:checked').map(x => x.value); if (!codes.length) { toast('Choose at least one cohort.', 'err'); return false; } const title = mval('#tn-t'), sched = mval('#tn-w') === 'sched'; STORE.tas.anns.unshift({ id: 'TA-' + Date.now(), title, aud: codes.map(c => (tasBatches().find(b => b.code === c) || {}).label).join(', '), ch: ['In-app', 'Email'], status: sched ? 'Scheduled' : 'Published', at: now().toISOString(), by: TME().name }); if (!sched) tasLearners(true).filter(l => l.v && codes.includes(l.batch.code)).forEach(l => { STORE.worlds[l.v].announcements.unshift({ id: 'ta' + Date.now() + l.v, title, from: TME().name, kind: 'Teacher', at: now().toISOString(), body: mval('#tn-b') }); notifyLearner(l.v, 'Other', 'New announcement', title, 'messages..announcements'); }); tasLog('Announcements', title, sched ? 'Scheduled' : 'Published', 'Draft', codes.join(', '), ''); render(); toast(sched ? 'Scheduled.' : 'Published to your cohorts.'); } }] });
INP.tnCount = () => { const codes = $$('.tn-b:checked').map(x => x.value); $('#tn-c').innerHTML = `Recipients: <strong>${tasLearners(true).filter(l => codes.includes(l.batch.code)).length}</strong>`; };

/* ---------- 6.13 My Approvals & Corrections (shared queue component, filtered) ---------- */
SCREENS['t-approvals'] = (p) => {
  const mine = allQueue().filter(i => i.raisedBy === TME().name);
  if (p.id) { const i = mine.find(x => x.id === p.id); if (!i) return tasDenied('queue item ' + p.id); let html = queueDetail(i.id); html = html.replace(/<section class="card"><h2>Decision<\/h2>[\s\S]*?<\/section>/, '').replace(/data-act="goTok" data-t="a-[^"]*"/g, 'data-act="tasNoop"').replace(/data-go="a-queue"/g, 'data-go="t-approvals"'); return html + (i.status === 'Info Requested' ? `<section class="card"><h2>Respond to the information request</h2><button class="btn btn-primary" data-act="tasRespond" data-id="${i.id}">Respond</button></section>` : '') + `<p class="xs muted">${ic('lock', 12)} You can't decide these items — the Academic Admin (or Super Administrator after 7 days) decides.</p>`; }
  const t = p.tab || 'recs';
  const st = subtabs([['recs', 'My recommendations'], ['dcs', 'My Data Correction Requests']], t, 't-approvals');
  const head = pageA('My Approvals & Corrections', 'Items you raised in the shared Approvals Queue', t === 'dcs' ? `<button class="btn btn-primary" data-act="tasDC">${ic('plus', 15)}Raise new</button>` : '');
  const rows = mine.filter(i => t === 'dcs' ? i.type === 'Data correction' : ['Resubmission limit reached', 'Discontinue enrolment — academic', 'Reactivate enrolment — academic'].includes(i.type));
  const disc = t === 'recs' && hasRole('Assessor') ? tasLearners(true).filter(l => l.status === 'Discontinued' && !l.short) : [];
  return head + st + (disc.length ? `<section class="card"><h2>Discontinued enrolments in my caseload</h2><ul class="list">${disc.map(l => `<li class="li"><div class="li-b"><strong>${esc(l.name)}</strong><span class="small muted">${esc(l.batch.label)} · Discontinued</span></div>${allQueue().some(i => i.type === 'Reactivate enrolment — academic' && isOpen(i) && (i.data || {}).lid === l.lid) ? chip('Reactivation requested', 'blue') : `<button class="btn btn-sm" data-act="tasReact" data-l="${l.lid}">Request reactivation</button>`}</li>`).join('')}</ul></section>` : '') + dt({ id: 'tapp-' + t, name: 'My approvals', rows, cols: [{ k: 'id', l: 'Item', h: i => `<a href="#t-approvals.${i.id}" data-go="t-approvals" data-id="${i.id}" class="mono">${i.id}</a>` }, { k: 'learner', l: 'Learner / record', v: i => i.related[0] }, ...(t === 'recs' ? [{ k: 'rec', l: 'My recommendation', v: i => (i.data || {}).rec || '—' }] : [{ k: 'cv', l: 'Current → proposed', h: i => `<span class="small"><span class="strike">${esc((i.data || {}).current || '')}</span> → ${esc((i.data || {}).proposed || '')}</span>` }]), { k: 'raised', l: 'Date', h: i => fd(i.raised), s: i => i.raised }, { k: 'status', l: 'Status', h: i => qchip(i.status) }, { k: 'by', l: 'Decided by', v: i => i.decidedBy || '—' }, { k: 'dec', l: 'Decision', h: i => `<span class="small">${esc(i.decision || '—')}${t === 'dcs' && i.status === 'Approved' ? ' — Corrected; original retained in history' : ''}</span>` }], act: i => `<button class="btn btn-sm" data-go="t-approvals" data-id="${i.id}">${i.status === 'Info Requested' ? 'Respond' : 'Open'}</button>`, empty: 'Nothing raised yet' });
};
ACT.tasReact = el => { const L = tasLearners(true).find(l => l.lid === el.dataset.l); reasonDlg({ title: 'Request reactivation — ' + esc(L.name), ok: 'Send request', label: 'Reason (required)', body: '<p class="small">The Academic Admin decides. If there is no decision in 7 days it goes to the Super Admin.</p>', onOk: r => { const id = 'AQ-' + (3300 + ADMIN.queue.length), at = now().toISOString(); ADMIN.queue.unshift({ id, type: 'Reactivate enrolment — academic', raisedBy: TME().name, raised: at, status: 'Pending', first: 'Rachel Hughes', related: [`${L.name} · ${L.batch.course || L.batch.label}`, 'a-learner.' + L.lid], reason: r, notes: [], history: [[TME().name, at, 'Raised', r]], data: { lid: L.lid } }); tasLog('Approvals Queue', id, 'Reactivation requested', '—', 'Pending', r); if (typeof acaNotify === 'function') acaNotify('Reactivation request', `${id} · ${L.name}`, 'a-queue.' + id, 'Approvals'); render(); toast(`${id} sent to the Academic Admin.`); } }); };
ACT.tasNoop = () => toast('Opens the record in your own views.', 'info');
ACT.tasRespond = el => reasonDlg({ title: 'Respond to the information request', ok: 'Send response', label: 'Your response', onOk: r => { const i = allQueue().find(x => x.id === el.dataset.id); i.notes.push([TME().name, now().toISOString(), r]); i.status = 'Pending'; tasLog('Approvals Queue', i.id, 'Responded to info request', 'Info Requested', 'Pending', r); render(); toast('Response added to the item.'); } });

/* ---------- 6.14 IQA Findings ---------- */
SCREENS['t-iqa'] = () => { const rows = ADMIN.iqa.filter(f => f.assessor === TME().name); return `${pageA('IQA Findings', 'On submissions you marked')}<div class="note b-blue">${ic('info')}<div class="small">Findings are visible to you and administrators only, never to learners. They do not change marks. Any correction goes through a Data Correction Request.</div></div>${dt({ id: 'tiqa', name: 'IQA findings', rows, cols: [{ k: 'text', l: 'Finding', h: f => `<span class="small">${esc(f.text)}</span>` }, { k: 'by', l: 'IQA' }, { k: 'at', l: 'Date', h: f => fd(f.at), s: f => f.at }, { k: 'sub', l: 'Learner · assignment', h: f => `<span class="small">${esc(f.sub)}</span>` }, { k: 'status', l: 'Status', h: f => chip(f.status || 'Open', { Open: 'amber', Acknowledged: 'blue', Closed: 'grey' }[f.status || 'Open']), v: f => f.status || 'Open' }], act: f => { const s = tasSubs(true).find(x => f.sub.startsWith(x.L.name + ' · ' + x.a.title.split(' —')[0])); return `${s ? `<button class="btn btn-sm" data-go="t-mark" data-id="${s.key}">Open submission</button> ` : ''}${(f.status || 'Open') === 'Open' ? `<button class="btn btn-sm btn-primary" data-act="iqaAck" data-id="${f.id}">Acknowledge</button>` : chip(f.status, f.status === 'Closed' ? 'grey' : 'blue')} <button class="btn btn-sm btn-ghost" data-act="tasDC" ${s ? `data-k="${s.key}"` : ''}>Raise Data Correction</button>`; }, empty: 'No IQA findings on your work' })}<p class="xs muted">Acknowledge a finding once you have read it. Sampling selection isn't available to assessors.</p>`; };
ACT.iqaRead = el => { S.tas.seen['iqa' + el.dataset.id] = true; render(); };
ACT.iqaAck = el => { const f = ADMIN.iqa.find(x => x.id === el.dataset.id); if (f.assessor !== TME().name) return; reasonDlg({ title: 'Acknowledge ' + f.id, ok: 'Acknowledge', label: 'Note for the IQA (required)', onOk: r => { f.status = 'Acknowledged'; f.ack = { by: TME().name, at: now().toISOString(), note: r }; S.tas.seen['iqa' + f.id] = true; tasLog('IQA Findings', f.id, 'Finding acknowledged', 'Open', 'Acknowledged', r); if (typeof iqaNotify === 'function') iqaNotify('Finding acknowledged by the assessor', `${f.id} · ${TME().name}: ${r}`, 'q-finding.' + f.id, f.by); render(); toast('Acknowledged. The IQA can now close the finding.'); } }); };

/* ---------- 6.15 Reports ---------- */
SCREENS['t-reports'] = () => { const subs = tasSubs(true), ls = tasLearners(true); return `${pageA('Reports', 'Permitted scope only. Every export is logged.')}<div class="grid-2"><section class="card"><div class="row-b"><h2>Individual learner progress</h2><button class="btn btn-sm" data-act="tasReport">Generate</button></div><p class="small muted">PDF per learner with purpose selector.</p></section>
  <section class="card"><div class="row-b"><h2>Cohort progress &amp; gap summary</h2>${exportMenu('Cohort progress & gap summary')}</div>${tasBatches().filter(b => !b.short).map(b => { const x = ls.filter(l => l.batch.code === b.code); return `<p class="small">${esc(b.label)}: ${x.length} learners · average ${x.length ? Math.round(x.reduce((a, l) => a + l.progress, 0) / x.length) : 0}% · ${x.filter(l => l.flags.includes('At risk')).length} at risk</p>`; }).join('')}</section>
  <section class="card"><div class="row-b"><h2>My marking activity</h2>${exportMenu('My marking activity')}</div><dl class="kv small"><dt>Released this month</dt><dd>${Object.keys(STORE.tas.marked).length + 18}</dd><dt>Average turnaround</dt><dd>4.2 days</dd><dt>Resubmission rate</dt><dd>${Math.round(subs.filter(s => s.status === 'Resubmission Required').length / Math.max(1, subs.filter(s => s.at).length) * 100)}%</dd><dt>Observations completed</dt><dd>${tasObs().filter(o => o.status === 'Completed').length}</dd></dl></section>
  ${CAN('attendance') !== 'no' ? `<section class="card"><div class="row-b"><h2>Attendance report</h2>${exportMenu('Attendance report')}</div><p class="small">${ls.filter(l => l.att != null && l.att < 80).length} learners below 80%.</p></section>` : ''}
  ${CAN('observations') !== 'no' ? `<section class="card"><h2>Observation log</h2>${dt({ id: 'lu-h-tobslog', name: 'Observation log', rows: tasObs().filter(o => o.at), rid: o => o.id || o.at + o.learner, cols: [{ k: 'learner', l: 'Learner' }, { k: 'at', l: 'Date', h: o => fd(o.at), v: o => o.at }, { k: 'status', l: 'Status', h: o => chip(o.status), v: o => o.status }] })}</section>` : ''}</div>`; };

/* ---------- 6.16 Notifications ---------- */
SCREENS['t-notifications'] = () => { const f = ui('tnf', 'All'), list = tasNotifs().filter(n => f === 'All' || (f === 'Unread' ? n.unread : n.cat === f)); return `${pageA('Notifications', '', `<button class="btn" data-act="tnReadAll">Mark all read</button>`)}${tabs(['All', 'Unread', 'Marking', 'Observations', 'Caseload', 'Sessions', 'General'].map(k => [k, k === 'Observations' ? 'Observations & PD' : k]), f, 'tnfTab', 'Filter')}${nfList('T', list, n => `<li class="li">${n.unread ? '<span class="unread-dot"></span><span class="sr">Unread</span>' : '<span class="read-dot"></span>'}<div class="li-b"><strong class="small">${esc(n.t)}</strong><span class="xs muted">${esc(n.b)} · ${fdt(n.at)}</span></div><button class="btn btn-sm btn-ghost" data-act="tnToggle" data-id="${n.id}">Mark ${n.unread ? 'read' : 'unread'}</button><button class="btn btn-sm" data-act="tnOpen" data-id="${n.id}">Open</button></li>`)}`; };
ACT.tnfTab = el => { setUi('tnf', el.dataset.k); render(); };
function tnSet(id, v) { const s = STORE.tas.notifs.find(x => x.id === id); if (s) s.unread = v; else S.tas.seen[id.slice(1)] = !v; }
ACT.tnToggle = el => { const n = tasNotifs().find(x => x.id === el.dataset.id); tnSet(n.id, !n.unread); render(); };
ACT.tnOpen = el => { const n = tasNotifs().find(x => x.id === el.dataset.id); tnSet(n.id, false); ACT.goTok({ dataset: { t: n.go } }); };
ACT.tnReadAll = () => { tasNotifs().forEach(n => tnSet(n.id, false)); render(); };

/* ---------- 6.17 My Profile ---------- */
SCREENS['t-profile'] = () => `${pageA('My Profile')}<div class="grid-2"><section class="card"><h2>Personal details</h2><dl class="kv"><dt>Name</dt><dd>${esc(TME().name)}</dd><dt>Email</dt><dd>${esc(TME().email)}</dd></dl><p class="small muted">Read-only — ask the System Administrator to change these.</p><h2>Professional details</h2><dl class="kv"><dt>Qualifications</dt><dd>${esc(TME().quals)}</dd><dt>Assessor registration</dt><dd class="mono">${esc(TME().reg)}</dd><dt>My roles</dt><dd>${TME().roles.map(r => chip(r, 'purple')).join(' ')}</dd></dl>
  <h2>My allocations</h2><ul class="list small">${tasBatches().map(b => `<li class="li"><div class="li-b"><strong>${esc(b.label)}</strong><span class="xs muted">${esc(b.course)} · since ${fd(b.start)}</span></div></li>`).join('')}</ul></section><section class="card"><h2>Change password</h2>${pwForm('tcp')}</section></div>${(() => { const rows = ADMIN.audit.filter(a => a.actor === TME().name); return `<section class="card"><h2>My recent activity</h2><ul class="list small">${rows.slice(0, 8).map(a => `<li class="li">${esc(a.action)} · ${esc(a.entity)} · ${fdt(a.at)}</li>`).join('') || '<li class="small muted">No activity yet.</li>'}</ul></section>`; })()}`;

/* ---------- Screen index ---------- */
SCREENS['t-index'] = () => { const L = (l, t) => `<li><button class="linklike" data-act="goTok" data-t="${t}">${l}</button></li>`; const lim = STORE.tas.limitKey; return `${pageA('Teacher / Assessor screen index')}<section class="card idx-sec"><h2>Screens</h2><ul class="idx-list">${TNAV.map(([r, l]) => L(l, r)).join('')}${L('Marking workspace — Aisha, Assignment 4 (first submission)', 't-mark.IA-L-18022~a4')}${L('Marking workspace — resubmission (Resub 1)', 't-mark.' + Object.keys(STORE.tas.over)[0])}${lim ? L('Marking workspace — resubmission limit → recommendation', 't-mark.' + lim) : ''}${L('Marking workspace — Aisha Assignment 7 (pending recommendation)', 't-mark.IA-L-18022~a7')}${L('Observation record (today)', 't-obsrec.TO-1')}${L('Observation report', 't-obsrec.TO-4')}${L('Learner — Aisha', 't-students.IA-L-18022')}${L('Register ZS-01', 't-sessions.ZS-01')}${L('Unmatched participants', 't-sessions..unmatched')}${L('Data corrections', 't-approvals..dcs')}${L('Unallocated learner (access denied)', 't-students.IA-L-31188')}</ul></section><section class="card"><p class="small">Variants, edge states and Demo only controls are in Demo controls.</p></section>`; };
const _idxT = SCREENS.index;
SCREENS.index = p => _idxT(p) + `<section class="card idx-sec"><h2>Teacher / Assessor</h2><ul class="idx-list">${[['A', 'Sign in as Teacher + Assessor (demo)'], ['T', 'Sign in as Teacher only'], ['S', 'Sign in as Assessor only'], ['M', 'Teacher/Assessor + Coordinator (multi-role)']].map(([v, l]) => `<li><button class="linklike" data-act="demoSignInAsTas" data-v="${v}">${l}</button></li>`).join('')}</ul></section>`;
AFTER.push(() => { const d = $('.demo-hint .row'); if (d && !S.signedIn && !d.querySelector('[data-act="demoSignInAsTas"]')) d.insertAdjacentHTML('beforeend', '<button type="button" class="btn btn-sm" data-act="demoSignInAsTas" data-v="A">Sign in as Teacher + Assessor (demo)</button><button type="button" class="btn btn-sm" data-act="demoSignInAsTas" data-v="T">Sign in as Teacher only</button><button type="button" class="btn btn-sm" data-act="demoSignInAsTas" data-v="S">Sign in as Assessor only</button>'); });

document.addEventListener('keydown', e => { const el = e.target.closest && e.target.closest('[role="button"][data-act]'); if (el && (e.key === 'Enter' || e.key === ' ') && el.tagName !== 'BUTTON') { e.preventDefault(); el.click(); } });

/* G6.1 (fix): Teacher-only users keep Progress & Gap Analysis read-only and the teaching reports */
const tasStripRec = h => h.replace(/<button class="btn btn-sm" data-act="tasRec"[^>]*>[^<]*<\/button>/g, '');
['t-progress', 't-students'].forEach(r => { const f = SCREENS[r]; SCREENS[r] = p => { const h = f(p); return hasRole('Assessor') ? h : tasStripRec(h).replace('<div class="page-h">', `<div class="note b-grey">${ic('lock')}<div class="small">Read-only for Teachers — recommendations and annotations are made by Assessors.</div></div><div class="page-h">`); }; });
const _tRepT = SCREENS['t-reports'];
SCREENS['t-reports'] = p => { const h = _tRepT(p); return hasRole('Assessor') ? h : h.replace(/<section class="card"><div class="row-b"><h2>My marking activity[\s\S]*?<\/section>/, ''); };
